sys_script_include.script:
var myOwnGrps = Class.create();
myOwnGrps.prototype = Object.extendsObject(AbstractAjaxProcessor, {


    myGrps: function() {
        var grpMem = []; //fetching the groups the logged in user is part of
        var myGroups = new GlideRecord('sys_user_grmember');
        myGroups.addQuery('user', gs.getUserID());
        myGroups.query();
        while (myGroups.next()) {
            grpMem.push(myGroups.group.sys_id);
        }
        var grpList = grpMem.toString(); //sys if of groups
        return grpList;

    },


    myGrpsName: function() {
        var grpMem = []; //fetching the groups the logged in user is part of
        var myGroups = new GlideRecord('sys_user_grmember');
        myGroups.addQuery('user', gs.getUserID());
        myGroups.query();
        while (myGroups.next()) {
            grpMem.push(myGroups.group.name);
        }
        var grpList = grpMem.toString(); //sys if of groups
        return grpList;

    },

    type: 'myOwnGrps'
});
